use android_tools::{
    generated_artifacts::{ModelConsumerVersion, parse_generated_artifacts},
    project_model::parse_model,
};
use anyhow::{Context as _, Result};
use std::{env, fs, path::PathBuf};
fn main() -> Result<()> {
    let mut arguments = env::args().skip(1);
    let first = arguments
        .next()
        .context("project root or --bridge-boundaries")?;
    if first == "--bridge-boundaries" {
        let path = arguments.next().context("bridge boundary JSON file")?;
        let value: serde_json::Value = serde_json::from_slice(&fs::read(path)?)?;
        for name in ["nullCollection", "wrongCollection", "nullMap", "wrongMap"] {
            assert_eq!(value[name]["status"], "unavailable", "{name}");
            assert!(
                value[name]["value"]["detail"]
                    .as_str()
                    .context("failure detail")?
                    .contains("unsupported type")
            );
        }
        for name in ["emptyCollection", "emptyMap"] {
            assert_eq!(value[name]["status"], "available", "{name}");
            assert_eq!(value[name]["value"], serde_json::json!([]), "{name}");
        }
        assert_eq!(
            value["orderedDuplicates"]["value"],
            serde_json::json!(["/tmp/z", "/tmp/a", "/tmp/z"])
        );
        assert_eq!(
            value["nullGetterAndroid"]["value"]["generatedSourceFolders"]["status"],
            "unavailable"
        );
        assert_eq!(
            value["emptyGetterAndroid"]["value"]["generatedSourceFolders"]["value"],
            serde_json::json!([])
        );
        assert_eq!(
            value["emptyGetterAndroid"]["value"]["sourceGenTaskName"]["value"],
            serde_json::Value::Null
        );
        for name in [
            "generatedResourceFolders",
            "generatedAssetsFolders",
            "sourceGenTaskName",
            "resGenTaskName",
        ] {
            assert_eq!(
                value["emptyGetterJava"]["value"][name]["status"], "notApplicable",
                "{name}"
            );
        }
        assert_eq!(value["absentArtifact"]["status"], "absent");
        println!(
            "Bridge null, malformed, empty, ordered duplicate, Android/Java and absent boundary assertions passed"
        );
        return Ok(());
    }
    let root = PathBuf::from(first).canonicalize()?;
    let output = fs::read_to_string(arguments.next().context("Gradle output file")?)?;
    let model = parse_model(&output, &root)?;
    let consumer = ModelConsumerVersion {
        major: 66,
        minor: 1,
        description: Some("supplementary raw V2 decoder".into()),
    };
    let facts = parse_generated_artifacts(&output, &model, 1, &consumer)?;
    facts.ensure_current(&model, 1)?;
    let modules = facts.modules();
    for module in modules {
        let versions = module.versions.available()?;
        for variant in module.variants.available()? {
            let selected = facts.variant(&module.module, &variant.name)?;
            assert_eq!(selected.name, variant.name);
            if let android_tools::generated_artifacts::ArtifactSlot::Present(artifact) =
                selected.main.available()?
            {
                artifact.generated_assets(versions)?;
                artifact.generated_class_paths(versions)?;
            }
        }
    }
    if let Some(inspection_file) = arguments.next() {
        let inspection: serde_json::Value = serde_json::from_slice(&fs::read(inspection_file)?)?;
        let mode = arguments
            .next()
            .context("source, bytecode, custom, disabled or disabled-artifact")?;
        let module = modules.first().context("module")?;
        let sdk_variants = inspection["variants"].as_array().context("SDK variants")?;
        let tasks = inspection["buildConfigTasks"]
            .as_array()
            .context("official BuildConfig tasks")?;
        let expected = match mode.as_str() {
            "source" | "custom" | "disabled-artifact" => Some("JAVA_SOURCE"),
            "bytecode" => Some("JAR"),
            "disabled" => None,
            _ => anyhow::bail!("Unsupported runtime mode {mode}"),
        };
        for variant in module.variants.available()? {
            let official = sdk_variants
                .iter()
                .find(|value| value["name"] == variant.name)
                .context("exact official variant identity")?;
            assert_eq!(official["type"]["status"], "available");
            assert_eq!(official["type"]["value"].as_str(), expected);
            let android_tools::generated_artifacts::ArtifactSlot::Present(main) =
                variant.main.available()?
            else {
                anyhow::bail!("main artifact absent")
            };
            let classpaths = main.generated_class_paths.available()?;
            match expected {
                Some("JAR") => {
                    let generated = classpaths
                        .iter()
                        .find(|value| value.name == "buildConfigGeneratedClasses")
                        .context("official BuildConfig generated classpath key")?;
                    assert!(
                        tasks
                            .iter()
                            .any(|task| task["bytecodeOutput"].as_str() == generated.path.to_str())
                    );
                    assert!(
                        !main
                            .generated_source_folders
                            .available()?
                            .contains(&generated.path)
                    );
                    assert!(generated.path.is_file());
                    assert!(fs::read(&generated.path)?.starts_with(b"PK"));
                }
                Some("JAVA_SOURCE") => {
                    assert!(
                        !classpaths
                            .iter()
                            .any(|value| value.name == "buildConfigGeneratedClasses")
                    );
                    let roots = main.generated_source_folders.available()?;
                    assert!(tasks.iter().any(|task| {
                        task["sourceOutput"]
                            .as_str()
                            .is_some_and(|path| roots.contains(&PathBuf::from(path)))
                    }));
                    if mode == "custom" {
                        let namespace = model
                            .modules
                            .iter()
                            .find(|value| value.path == module.module)
                            .and_then(|value| value.namespace.as_deref())
                            .context("main namespace")?;
                        let main_tasks = tasks
                            .iter()
                            .filter(|task| task["namespace"].as_str() == Some(namespace))
                            .collect::<Vec<_>>();
                        assert!(!main_tasks.is_empty());
                        assert!(main_tasks.iter().all(|task| {
                            task["customFields"].as_array().is_some_and(|fields| {
                                fields.contains(&serde_json::json!("FACT_STRING"))
                            })
                        }));
                    }
                }
                None => {
                    assert!(tasks.is_empty());
                    assert!(
                        !classpaths
                            .iter()
                            .any(|value| value.name == "buildConfigGeneratedClasses")
                    );
                }
                _ => anyhow::bail!("unproved BuildConfig mode"),
            }
            let build = module.build_folder.available()?;
            for roots in [
                main.generated_resource_folders.available()?,
                main.generated_assets_folders.available()?,
            ] {
                assert!(
                    roots
                        .iter()
                        .any(|path| path.starts_with(&model.root) && !path.starts_with(build))
                );
            }
            assert!(matches!(
                variant.fixtures.available()?,
                android_tools::generated_artifacts::ArtifactSlot::Absent
            ));
        }
        if mode == "disabled-artifact" {
            assert!(
                facts
                    .variant(&module.module, "demoRelease")?
                    .host_tests
                    .available()?
                    .is_empty()
            );
            assert!(
                !facts
                    .variant(&module.module, "demoDebug")?
                    .host_tests
                    .available()?
                    .is_empty()
            );
            assert!(
                facts
                    .variant(&module.module, "demoRelease")?
                    .device_tests
                    .available()?
                    .is_empty()
            );
        }
        assert_eq!(
            facts
                .variant(&module.module, "inactiveDebug")
                .unwrap_err()
                .reason,
            android_tools::project_tree_facts::FactsUnavailableReason::MissingVariant
        );
    }
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({"supplementaryOnly":true,
        "originalReferenceRuntimeTestCredit":0,"root":model.root,"modules":modules,"revisionBindingVerified":true}))?
    );
    Ok(())
}
